CREATE POLICY customer_device_select ON public.customer_device FOR SELECT TO authenticated
  USING (public.has_permission('A-CUS-010', 'READ'));
--> statement-breakpoint
CREATE POLICY coupon_select ON public.coupon FOR SELECT TO authenticated
  USING (public.has_permission('A-CRM-030', 'READ'));
--> statement-breakpoint
CREATE POLICY customer_coupon_select ON public.customer_coupon FOR SELECT TO authenticated
  USING (public.has_permission('A-CRM-030', 'READ'));
