CREATE POLICY review_select ON public.review FOR SELECT TO authenticated
  USING (public.has_permission('A-VOC-040', 'READ') AND (branch_id IS NULL OR public.can_access_branch(branch_id)));
--> statement-breakpoint
CREATE POLICY material_usage_select ON public.material_usage FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM work_order w JOIN service_order o ON o.id = w.order_id WHERE w.id = work_order_id
    AND public.has_permission('A-PRC-010', 'READ') AND public.can_access_branch(o.branch_id)));
--> statement-breakpoint
