INSERT INTO public.notification_template (template_code, channel, target, title, body) VALUES
  ('REVIEW_REQUEST', 'ALIMTALK', 'CUSTOMER', '후기 요청', E'#{고객명}님, 에어컨 청소는 만족스러우셨나요?\n#{접수번호} 작업 후기를 #{마감일}까지 남겨 주세요.\n후기 쓰기: #{후기링크}'),
  ('COUPON_ISSUED', 'ALIMTALK', 'CUSTOMER', '쿠폰 발급 안내', E'#{고객명}님, #{쿠폰명} 쿠폰이 발급되었습니다.\n사용 기한: #{사용기한}까지\n마이 > 쿠폰함에서 확인해 주세요.'),
  ('CAMPAIGN_MESSAGE', 'ALIMTALK', 'CUSTOMER', '이벤트 안내', E'#{고객명}님, #{캠페인명} 소식을 알려 드려요.\n#{쿠폰안내}\n예약하기: #{예약링크}\n수신을 원하지 않으시면 마이 > 동의 관리에서 해제할 수 있어요.'),
  ('INSPECTION_REJECTED', 'PUSH', 'TECHNICIAN', '작업 결과 반려(재작업 요청)', E'#{접수번호} 작업 결과가 반려되었습니다.\n사유: #{사유}\n거점에 연락해 재작업 일정을 맞춰 주세요.'),
  ('ETA_DELAY_TECH', 'PUSH', 'TECHNICIAN', '다음 고객 지연 예상', E'#{접수번호} 고객 도착이 약 #{지연분}분 늦을 것 같아요(예상 #{도착예정}).\n코스 화면에서 고객에게 지연 안내를 보낼 수 있어요.'),
  ('VISIT_DELAY', 'ALIMTALK', 'CUSTOMER', '방문 지연 안내', E'#{고객명}님, 앞 작업이 길어져 기사님 도착이 늦어질 것 같아요.\n도착 예정: #{도착예정}\n접수번호: #{접수번호}\n불편을 드려 죄송합니다. 문의: #{거점전화}'),
  ('ROUTE_CHANGE_REQUESTED', 'PUSH', 'ADMIN', '코스 변경 요청', E'#{기사명} 기사가 #{코스일자} 코스 변경을 요청했습니다.\n사유: #{사유}'),
  ('ROUTE_CHANGE_APPROVED', 'PUSH', 'TECHNICIAN', '코스 변경 승인', E'#{코스일자} 코스 변경이 승인되었습니다. 순서를 고친 뒤 다시 확정해 주세요.'),
  ('ROUTE_CHANGE_REJECTED', 'PUSH', 'TECHNICIAN', '코스 변경 반려', E'#{코스일자} 코스 변경 요청이 반려되었습니다.\n#{사유}'),
  ('DORMANT_NOTICE', 'ALIMTALK', 'CUSTOMER', '휴면 전환 예정 안내', E'#{고객명}님, 오래 이용하지 않아 #{전환일}에 휴면 계정으로 바뀔 예정입니다.\n계속 이용하시려면 그 전에 로그인해 주세요.'),
  ('PG_MISMATCH', 'PUSH', 'ADMIN', 'PG 대사 불일치', E'#{대사일} PG 대사에서 불일치 #{건수}건이 나왔습니다. 결제 내역(A-PAY-010)에서 확인해 주세요.')
ON CONFLICT (template_code) DO NOTHING;
